#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

SKILL_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
CONFIG_ROOT=${AAPANEL_CONFIG_ROOT:-"$HOME/.config/aapanel"}
SERVERS_DIR="$CONFIG_ROOT/servers"
CREDENTIALS_DIR="$CONFIG_ROOT/credentials"

banner "aaPanel VPS registration"

stage "Server identity"
say "Choose a stable alias so every deployment can ask for the exact VPS."
while true; do
  ask VPS_ALIAS "Alias (lowercase letters, numbers, hyphens):"
  if [[ "$VPS_ALIAS" =~ ^[a-z0-9][a-z0-9-]*$ ]]; then
    break
  fi
  warn "invalid alias: use lowercase letters, numbers, and single hyphens; try again"
done
ask VPS_PURPOSE "Provider or purpose (for example Hetzner production):"
ask VPS_ENVIRONMENT "Environment (production/staging/other):"

stage "aaPanel and site"
while true; do
  ask AAPANEL_URL "Full aaPanel URL including port and security entrance:"
  if [[ "$AAPANEL_URL" =~ ^https://[^/]+/.+ ]]; then
    break
  fi
  warn "the URL must start with https:// and include the security entrance path; try again"
done
ask AAPANEL_USER "aaPanel username:"
ask SITE_DOMAIN "Primary domain hosted on this VPS:"
while true; do
  ask SITE_WEBROOT "Exact webroot (for example /www/wwwroot/example.com):"
  if [[ "$SITE_WEBROOT" == /* ]]; then
    break
  fi
  warn "webroot must be an absolute server path; try again"
done

stage "Certificate identity"
say "The wizard will display the certificate currently presented by the server."
step "Compare it with the certificate fingerprint shown by aaPanel or your VPS provider."
AAPANEL_FINGERPRINT=$(python3 - "$SKILL_DIR" "$AAPANEL_URL" <<'PY'
import sys
sys.path.insert(0, sys.argv[1])
from aa_client import AaPanel
print(AaPanel.fetch_fingerprint(sys.argv[2]))
PY
)
printf '  %sPresented SHA-256:%s %s\n' "$BOLD" "$RESET" "$AAPANEL_FINGERPRINT"
open_url "$AAPANEL_URL"
if ! confirm "Does this fingerprint match the trusted VPS/aaPanel certificate view?"; then
  warn "certificate identity was not accepted; nothing was saved"
  exit 1
fi

stage "Credential storage"
say "The password is entered invisibly and stored separately with mode 0600."
while true; do
  ask_secret AAPANEL_PASSWORD "aaPanel password:"
  ask_secret AAPANEL_PASSWORD_CONFIRM "Repeat the password:"
  if [[ -n "$AAPANEL_PASSWORD" && "$AAPANEL_PASSWORD" == "$AAPANEL_PASSWORD_CONFIRM" ]]; then
    break
  fi
  warn "passwords were empty or did not match; try again"
done
PROFILE_PATH="$SERVERS_DIR/$VPS_ALIAS.json"
PASSWORD_PATH="$CREDENTIALS_DIR/$VPS_ALIAS.password"
if [[ -e "$PROFILE_PATH" || -e "$PASSWORD_PATH" ]]; then
  if ! confirm "Profile '$VPS_ALIAS' already exists. Back it up and replace it?"; then
    warn "existing profile preserved"
    exit 1
  fi
fi
mkdir -p "$SERVERS_DIR" "$CREDENTIALS_DIR"
chmod 0700 "$CONFIG_ROOT" "$SERVERS_DIR" "$CREDENTIALS_DIR"
if [[ -f "$PROFILE_PATH" ]]; then
  cp -p "$PROFILE_PATH" "$PROFILE_PATH.bak.$(date -u +%Y%m%dT%H%M%SZ)"
fi
if [[ -f "$PASSWORD_PATH" ]]; then
  cp -p "$PASSWORD_PATH" "$PASSWORD_PATH.bak.$(date -u +%Y%m%dT%H%M%SZ)"
fi
umask 077
PASSWORD_TMP=$(mktemp "$CREDENTIALS_DIR/.${VPS_ALIAS}.password.XXXXXX")
PROFILE_TMP=$(mktemp "$SERVERS_DIR/.${VPS_ALIAS}.json.XXXXXX")
printf '%s' "$AAPANEL_PASSWORD" > "$PASSWORD_TMP"
python3 - "$PROFILE_TMP" "$AAPANEL_URL" "$AAPANEL_USER" "$PASSWORD_PATH" \
  "$AAPANEL_FINGERPRINT" "$VPS_PURPOSE" "$VPS_ENVIRONMENT" "$SITE_DOMAIN" "$SITE_WEBROOT" <<'PY'
import json
import sys
path, url, user, password_file, fingerprint, purpose, environment, domain, webroot = sys.argv[1:]
profile = {
    "url": url,
    "user": user,
    "password_file": password_file,
    "fingerprint": fingerprint,
    "purpose": purpose,
    "environment": environment,
    "sites": [{"domain": domain, "webroot": webroot}],
}
with open(path, "w", encoding="utf-8") as handle:
    json.dump(profile, handle, ensure_ascii=False, indent=2)
    handle.write("\n")
PY
chmod 0600 "$PASSWORD_TMP" "$PROFILE_TMP"
mv "$PASSWORD_TMP" "$PASSWORD_PATH"
mv "$PROFILE_TMP" "$PROFILE_PATH"
unset AAPANEL_PASSWORD AAPANEL_PASSWORD_CONFIRM
say "Saved profile and credential with private permissions."

stage "Read-only validation"
say "Logging in and listing only the selected webroot. No server file will be changed."
python3 - "$SKILL_DIR" "$PROFILE_PATH" "$SITE_WEBROOT" <<'PY'
import sys
sys.path.insert(0, sys.argv[1])
from aa_client import AaPanel
panel = AaPanel.from_config(sys.argv[2]).login()
result = panel.listdir(sys.argv[3])
if not isinstance(result, dict):
    raise SystemExit("aaPanel returned an unexpected directory response")
if result.get("status") is False:
    raise SystemExit(f"aaPanel rejected the webroot: {result.get('msg', result)}")
print("  ✓ login succeeded and the configured webroot is readable")
PY
note "profile: $PROFILE_PATH"
note "credential: $PASSWORD_PATH"
note "site: $SITE_DOMAIN → $SITE_WEBROOT ($VPS_ENVIRONMENT)"

finish
